package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type Document struct {
	ID       int    `json:"id"`
	Title    string `json:"title"`
	Content  string `json:"content"`
	OwnerID  int    `json:"owner_id"`
	Classify string `json:"classification"`
}

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// searchDocuments handles full-text search with filtering
func searchDocuments(w http.ResponseWriter, r *http.Request) {
	if r.Method != "GET" {
		http.Error(w, "Method not allowed", 405)
		return
	}

	query := r.URL.Query().Get("q")
	classification := r.URL.Query().Get("class")
	ownerFilter := r.URL.Query().Get("owner")

	// Build base query with parameterized search term
	baseQuery := "SELECT id, title, content, owner_id, classification FROM documents WHERE to_tsvector('english', title || ' ' || content) @@ plainto_tsquery('english', $1)"
	args := []interface{}{query}
	argIdx := 2

	// Classification filter - validated against known values
	validClasses := map[string]bool{"public": true, "internal": true, "confidential": true, "restricted": true}
	if classification != "" && validClasses[strings.ToLower(classification)] {
		baseQuery += fmt.Sprintf(" AND classification = $%d", argIdx)
		args = append(args, classification)
		argIdx++
	}

	// Owner filter - VULNERABLE: string concatenation for IN clause
	// Developer note: parameterized IN clauses are complex in Go, using string building
	// The owner param accepts comma-separated IDs like "1,2,3"
	if ownerFilter != "" {
		// Attempt at validation - only checks first character
		if ownerFilter[0] >= '0' && ownerFilter[0] <= '9' {
			baseQuery += " AND owner_id IN (" + ownerFilter + ")"
		}
	}

	baseQuery += fmt.Sprintf(" LIMIT $%d", argIdx)
	args = append(args, 50)

	rows, err := db.Query(baseQuery, args...)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Search failed", 500)
		return
	}
	defer rows.Close()

	var results []Document
	for rows.Next() {
		var doc Document
		if err := rows.Scan(&doc.ID, &doc.Title, &doc.Content, &doc.OwnerID, &doc.Classify); err != nil {
			continue
		}
		results = append(results, doc)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(results)
}

// healthCheck for ALB target group
func healthCheck(w http.ResponseWriter, r *http.Request) {
	err := db.Ping()
	if err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	w.WriteHeader(200)
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/search", searchDocuments)
	http.HandleFunc("/health", healthCheck)
	log.Fatal(http.ListenAndServe(":8080", nil))
}
